# Generated by manage.py generate_test_cases.
from django.contrib.auth.models import Group
from django.utils import timezone

from bloomerp.models.tutorial import (
    Tutorial,
    TutorialProgress,
    TutorialRevision,
    TutorialStep,
)
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestEligibleTutorialsView(BloomerpAPIViewTestCase):
    """Tests class `EligibleTutorialsView` from `bloomerp/views/api/tutorials/eligible_tutorials.py`."""

    view_name = "eligible_tutorials"

    def extendedSetup(self) -> None:
        """Create revisions from different audiences, publication states, and versions."""
        public = Tutorial.objects.create(name="Public", available_to_all=True)
        self.make_revision(public, 1)
        self.public = self.make_revision(public, 2)
        self.make_revision(public, 3, published=False)
        direct = Tutorial.objects.create(name="Direct")
        direct.assigned_users.add(self.normal_user)
        self.direct = self.make_revision(direct, 1)
        TutorialProgress.objects.create(
            revision=self.direct, user=self.normal_user, first_shown_at=timezone.now()
        )
        group = Group.objects.create(name="Tutorial learners")
        self.normal_user.groups.add(group)
        grouped = Tutorial.objects.create(name="Group")
        grouped.assigned_groups.add(group)
        self.grouped = self.make_revision(grouped, 1)
        matching_filter = [
            {
                "connector": "AND",
                "conditions": [
                    {
                        "field_path": "username",
                        "lookup_id": "equals",
                        "value": self.normal_user.get_username(),
                    }
                ],
            }
        ]
        self.filtered = self.make_revision(
            Tutorial.objects.create(
                name="Filtered", available_to_all=True, user_filter=matching_filter
            ),
            1,
        )
        self.make_revision(
            Tutorial.objects.create(name="Filter without assignment", user_filter=matching_filter),
            1,
        )
        self.make_revision(
            Tutorial.objects.create(
                name="Malformed filter", available_to_all=True, user_filter={"invalid": True}
            ),
            1,
        )
        self.make_revision(Tutorial.objects.create(name="Private"), 1)
        self.make_revision(
            Tutorial.objects.create(
                name="Inactive", available_to_all=True, is_active=False
            ),
            1,
        )

    def make_revision(
        self, tutorial: Tutorial, number: int, *, published: bool = True
    ) -> TutorialRevision:
        """Create a revision with a step so it is eligible when published."""
        revision = TutorialRevision.objects.create(
            tutorial=tutorial,
            number=number,
            published_at=timezone.now() if published else None,
            trigger_route="home",
            auto_start=True,
        )
        TutorialStep.objects.create(
            revision=revision, key="welcome", sequence=1, name="Welcome", text="Welcome"
        )
        return revision

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check that the catalog carries only current, eligible route metadata."""
        return [
            RequestScenario(
                name="Learner receives only current published tutorials for their audiences",
                user=self.normal_user,
                expected=ExpectedResult(
                    response_validators=[
                        self.json_exact(
                            {
                                "tutorials": [
                                    {
                                        "revision_id": str(revision.pk),
                                        "name": revision.tutorial.name,
                                        "trigger_route": "home",
                                        "auto_start": auto_start,
                                    }
                                    for revision, auto_start in (
                                        (self.direct, False),
                                        (self.filtered, True),
                                        (self.grouped, True),
                                        (self.public, True),
                                    )
                                ]
                            }
                        ),
                        self.header_equals("Cache-Control", "private, no-store"),
                    ],
                ),
            ),
            RequestScenario(
                name="Anonymous access is denied",
                expected=ExpectedResult(status_code=403),
            ),
        ]
